+package policy
+
+import (
+	"path"
+	"strings"
+)
+
+// cleanRepoPath puts a repository-relative path in the slash-separated,
+// cleaned form the constraint tables are written in: surrounding whitespace
+// is trimmed, backslashes become slashes, a leading "./" is dropped and "."
+// and ".." segments are resolved.
+func cleanRepoPath(p string) string {
+	p = strings.TrimSpace(p)
+	p = strings.ReplaceAll(p, `\`, "/")
+	p = strings.TrimPrefix(p, "./")
+	if p == "" {
+		return ""
+	}
+	return path.Clean(p)
+}
+
+// foldRepoPath is cleanRepoPath followed by strings.ToLower.
+func foldRepoPath(p string) string {
+	return strings.ToLower(cleanRepoPath(p))
+}
