@@ -0,0 +1,35 @@
+package policy
+
+import "testing"
+
+func TestCleanRepoPath(t *testing.T) {
+	for _, tc := range []struct{ in, want string }{
+		{`backend\internal\server\routes.go`, "backend/internal/server/routes.go"},
+		{"./docs/README.md", "docs/README.md"},
+		{"docs/../README.md", "README.md"},
+		{"  scripts/test ", "scripts/test"},
+		{"", ""},
+	} {
+		if got := cleanRepoPath(tc.in); got != tc.want {
+			t.Errorf("cleanRepoPath(%q) = %q, want %q", tc.in, got, tc.want)
+		}
+	}
+}
+
+func TestCheckScope_WindowsSeparators(t *testing.T) {
+	c := InstructionPathConstraint{}
+	got := c.CheckScope([]plan.ScopeFile{{Path: `docs\CLAUDE.md`}, {Path: `backend\internal\server\routes.go`}})
+	if len(got) != 1 || got[0].Path != `docs\CLAUDE.md` {
+		t.Fatalf("violations = %+v, want exactly docs\\CLAUDE.md", got)
+	}
+}
+
+func TestCheckChanged_DotSlashPrefix(t *testing.T) {
+	c := InstructionPathConstraint{}
+	got := c.CheckChanged([]ChangedFile{{Path: "./CLAUDE.md"}, {Path: "./docs/README.md"}})
+	if len(got) != 1 || got[0].Path != "./CLAUDE.md" {
+		t.Fatalf("violations = %+v, want exactly ./CLAUDE.md", got)
+	}
+}
